<include file="Public:header"/><div class="mainbox">	<div id="nav" class="mainnav_title">		<ul>			<a href="{pigcms{:U('Deliver/level_list')}">等级管理</a>|			<a href="javascript:void(0);"  onclick="window.o2oTop.artiframe('{pigcms{:U('level_add')}','添加等级',800,560,true,false,false,editbtn,'edit',true);">添加等级</a>			<a href="{pigcms{:U('Deliver/config_level')}" class="on">等级配置</a>|			<a href="{pigcms{:U('Deliver/level_rule_list')}">等级规则配置</a>		</ul>	</div>	<form id="myform" method="post" action="{pigcms{:U('Deliver/config_level')}" frame="true" refresh="true">		<table cellpadding="0" cellspacing="0" class="frame_form" width="100%">			<volist name="config_list" id="vo">				<if condition="$vo['name'] eq 'open_deliver_level'">					<tr>		                <th width="160">{pigcms{$vo.info}</th>		                <td>		                    <span class="cb-enable"><label class="cb-enable <if condition="$vo['value'] eq 1">selected</if>"><span>开启</span>		                    <input type="radio" name="{pigcms{$vo.name}" value="1" <if condition="$vo['value'] eq 1">checked="checked"</if>/></label></span>		                    <span class="cb-disable " ><label class="cb-disable  <if condition="$vo['value'] eq 0">selected</if>"><span>关闭</span>		                    <input type="radio" name="{pigcms{$vo.name}" value="0" <if condition="$vo['value'] eq 0" tips="{pigcms{$vo.desc}">checked="checked"</if>/></label></span>		                </td>		            </tr>		        <elseif condition="!in_array($vo['name'], array('deliver_level_down_days','deliver_level_down_num','deliver_level_down_score'))"/>					<tr>  						<th width="160">{pigcms{$vo.info}</th>		                <td>							<input type="text" class="input fl" name="{pigcms{$vo.name}" size="10" validate="required:true;number:true" value="{pigcms{$vo.value}"   tips="{pigcms{$vo.desc}"/>		                </td>		            </tr>				</if>			</volist>			<tr>				<th width="15%">降级设置</th>				<td width="35%">                   <input type="text" class="input" name="deliver_level_down_days" value="{pigcms{$deliver_level_down_days}" size="5" placeholder="" validate="number:true"/>天以内，未完成                   <input type="text" class="input" name="deliver_level_down_num" value="{pigcms{$deliver_level_down_num}" size="5"  placeholder="" validate="number:true"/>单，扣除等级积分                   <input type="text" class="input" name="deliver_level_down_score" value="{pigcms{$deliver_level_down_score}" size="5"  placeholder="" validate="number:true" tips="任意一个设置为0，该功能无效"/>               </td>			</tr>						</table>		<div class="btn">			<input type="submit" name="dosubmit" id="dosubmit" value="提交" class="button" />		</div>	</form></div><include file="Public:footer"/>